 22	        description: description.slice(0, 200),
 23	        tier: result.recommendedTier,
 24	        host: result.recommendedHost,
 25	        model: result.recommendedModel,
 26	        fallback: result.fallback,
 27	        reasoning: result.reasoning,
 28	      });
 29	      return jsonContent(result);
 30	    }
 31	  );
