 33	  server.tool(
 34	    "route_parallel_tasks",
 35	    "Given multiple task descriptions, produce a hardware-aware parallel delegation schedule across local and remote hosts",
 36	    {
 37	      tasks: z
 38	        .array(z.string())
 39	        .min(1)
 40	        .max(128)
 41	        .describe("Task descriptions to schedule in parallel"),
 42	    },
 43	    async ({ tasks }) => {
 44	      const registry = await deps.loadRegistry();
 45	      const schedule = routeParallelTasks(tasks, registry);
 46	      const assignments = schedule.assignments as Array<Record<string, unknown>>;
 47	      void logEvent("server", "route_parallel_tasks.result", {
 48	        taskCount: tasks.length,
 49	        assignedCount: assignments.filter((a) => a["status"] !== "unassigned").length,
 50	        unassignedCount: assignments.filter((a) => a["status"] === "unassigned").length,
 51	        hostUtilization: schedule.hostUtilization,
 52	      });
 53	      return jsonContent(schedule);
 54	    }
 55	  );
 56	
 57	  server.tool(
 58	    "route_task_with_watchdog",
 59	    "Route a task with host/model liveness checks and automatic failover recommendations",
 60	    {
 61	      description: z.string().describe("Description of the task to route"),
 62	      preferredHost: z
 63	        .string()
 64	        .optional()
 65	        .describe("Optional host ID override for the primary attempt"),
 66	      preferredModel: z
 67	        .string()
 68	        .optional()
 69	        .describe("Optional model override for the primary attempt"),
 70	      maxFallbacks: z
 71	        .number()
 72	        .int()
 73	        .min(1)
 74	        .max(8)
 75	        .optional()
 76	        .describe("Maximum fallback hosts to probe"),
 77	    },
