import { execSync } from "node:child_process";
import { existsSync, readFileSync, statSync } from "node:fs";
import { readdir, readFile } from "node:fs/promises";
import { join, relative, resolve } from "node:path";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface RepoMapFile {
  path: string;
  score: number;
  ranges: Array<{ startLine: number; endLine: number }>;
  symbols?: string[];
}

export interface RepoMapResult {
  files: RepoMapFile[];
  tokensEstimated: number;
  method: "heuristic" | "treesitter";
}

export interface BuildRepoMapOptions {
  root: string;
  tokenBudget?: number;
  focusPaths?: string[];
  includeSymbols?: boolean;
}

// ---------------------------------------------------------------------------
// Ignore-file helpers
// ---------------------------------------------------------------------------

/** Parse a gitignore-style file into an array of minimatch-like patterns. */
function parseIgnoreFile(path: string): string[] {
  const content = readFileSync(path, "utf8");
  const patterns: string[] = [];
  for (const line of content.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    patterns.push(trimmed);
  }
  return patterns;
}

/** Load .xxignore and .gitignore patterns for a given root directory. */
function loadIgnorePatterns(root: string): string[] {
  const patterns: string[] = [];
  for (const name of [".xxignore", ".gitignore"]) {
    const p = join(root, name);
    if (existsSync(p)) {
      patterns.push(...parseIgnoreFile(p));
    }
  }
  return patterns;
}

/**
 * Check if a path matches an ignore pattern.
 * Supports leading `/` (anchor to root), trailing `/` (directory only), and
 * basic `**` globs.  This is intentionally simple — the real gitignore spec
 * is complex, and we only need to catch the common patterns used in these
 * repos.
 */
function isIgnored(relPath: string, patterns: string[], root: string): boolean {
  for (const pattern of patterns) {
    // Trim leading slash — it means "anchored to repo root"
    const anchored = pattern.startsWith("/");
    const p = anchored ? pattern.slice(1) : pattern;

    // Directory-only marker
    const dirOnly = p.endsWith("/");
    const base = dirOnly ? p.slice(0, -1) : p;

    // Check if the path matches the pattern
    if (matchGlobLike(relPath, base, anchored)) return true;
    // Also check if any parent directory matches a dir-only pattern
    if (dirOnly && relPath.startsWith(base + "/")) return true;
  }
  return false;
}

/** Simple glob-like matcher (supports `*`, `**`, leading `**/`). */
function matchGlobLike(path: string, pattern: string, anchored: boolean): boolean {
  // If anchored, the pattern must match from the start of the relative path
  // If not anchored, it can match at any level

  if (pattern === "**") return true;

  // Handle **/ prefix
  if (pattern.startsWith("**/")) {
    const rest = pattern.slice(3);
    // Try matching at every level
    let p = path;
    while (true) {
      if (simpleMatch(p, rest)) return true;
      const idx = p.indexOf("/");
      if (idx < 0) break;
      p = p.slice(idx + 1);
    }
    return false;
  }

  // Handle trailing /** (match everything inside a directory)
  if (pattern.endsWith("/**")) {
    const prefix = pattern.slice(0, -3);
    return path === prefix || path.startsWith(prefix + "/");
  }

  if (anchored) {
    return simpleMatch(path, pattern);
  }

  // Non-anchored: match at any level or as a suffix
  if (simpleMatch(path, pattern)) return true;
  // Also match the last component
  const basename = path.split("/").pop() ?? path;
  if (simpleMatch(basename, pattern)) return true;

  return false;
}

/** Match a single path component against a simple glob (supports `*` and `?`). */
function simpleMatch(path: string, pattern: string): boolean {
  // Fast path for literal match
  if (!pattern.includes("*") && !pattern.includes("?")) {
    return path === pattern;
  }

  // Convert glob to regex (very basic — handles * and ?)
  const regexStr =
    "^" +
    pattern
      .replace(/[.+^${}()|[\]\\]/g, "\\$&")
      .replace(/\*/g, "[^/]*")
      .replace(/\?/g, "[^/]") +
    "$";
  try {
    return new RegExp(regexStr).test(path);
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// File discovery
// ---------------------------------------------------------------------------

/** Recursively list all files under a directory, respecting ignore patterns. */
async function discoverFiles(
  root: string,
  ignorePatterns: string[]
): Promise<string[]> {
  const results: string[] = [];

  async function walk(dir: string): Promise<void> {
    let entries: string[];
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      const fullPath = join(dir, entry.name);
      const relPath = relative(root, fullPath);

      if (isIgnored(relPath, ignorePatterns, root)) continue;

      if (entry.isDirectory()) {
        await walk(fullPath);
      } else if (entry.isFile()) {
        results.push(relPath);
      }
    }
  }

  await walk(root);
  return results;
}

// ---------------------------------------------------------------------------
// Scoring signals
// ---------------------------------------------------------------------------

interface FileSignals {
  path: string;
  gitTimestamp: number;
  proximityScore: number;
  refCount: number;
}

/**
 * Get the latest git commit timestamp for a file (as Unix epoch ms).
 * Returns 0 if the file is not tracked by git.
 */
function getGitTimestamp(filePath: string, cwd: string): number {
  try {
    const rel = relative(cwd, filePath);
    const out = execSync(
      `git log -1 --format=%ct -- "${rel}" 2>/dev/null || echo "0"`,
      { cwd, encoding: "utf8", timeout: 5000 }
    );
    const ts = parseInt(out.trim(), 10);
