  const maxRef = Math.max(...signals.map((s) => s.refCount), 1);

  for (const s of signals) {
    const recency = s.gitTimestamp / maxTs;          // 0..1
    const refNorm = s.refCount / maxRef;              // 0..1
    const focus = s.proximityScore;                   // 0..1

    // Weighted combination: recency 30%, refs 30%, focus 40%
    s.proximityScore = recency * 0.3 + refNorm * 0.3 + focus * 0.4;
