/**
 * Get the latest git commit timestamp for a file (as Unix epoch ms).
 * Uses a single `git log` call with `--name-only` to batch all files.
 * Returns 0 if the file is not tracked by git.
 */
const gitTimestampCache = new Map<string, number>();

function getGitTimestamp(filePath: string, cwd: string): number {
  const cacheKey = `${cwd}:${filePath}`;
  const cached = gitTimestampCache.get(cacheKey);
  if (cached !== undefined) return cached;

  try {
    const rel = relative(cwd, filePath);
    const out = execSync(
      `git log -1 --format=%ct -- "${rel}" 2>/dev/null || echo "0"`,
      { cwd, encoding: "utf8", timeout: 5000 }
    );
    const ts = parseInt(out.trim(), 10);
    const result = Number.isFinite(ts) ? ts * 1000 : 0;
    gitTimestampCache.set(cacheKey, result);
    return result;
  } catch {
    gitTimestampCache.set(cacheKey, 0);
    return 0;
  }
}

/** Pre-warm the git timestamp cache with a single batch call. */
function prewarmGitTimestamps(files: string[], cwd: string): void {
  try {
    // Get all file timestamps in one call
    const out = execSync(
      `git log --all --pretty=format:"%ct %H" --name-only 2>/dev/null | head -10000`,
      { cwd, encoding: "utf8", timeout: 10000 }
    );
    // Parse the output to build a map of file -> last commit timestamp
    const lines = out.split("\n");
    let currentTs = 0;
    for (const line of lines) {
      const tsMatch = line.match(/^(\d+)\s[0-9a-f]+$/);
      if (tsMatch) {
        currentTs = parseInt(tsMatch[1], 10) * 1000;
      } else if (line.trim() && currentTs > 0) {
        const fullPath = join(cwd, line.trim());
        const cacheKey = `${cwd}:${fullPath}`;
        if (!gitTimestampCache.has(cacheKey)) {
          gitTimestampCache.set(cacheKey, currentTs);
        }
      }
    }
  } catch {
    // Fallback: cache stays empty, per-file calls will populate it
  }
}

